import * as THREE from 'three';

export function axialToWorld(q, r, size) {
  const x = size * Math.sqrt(3) * (q + r / 2);
  const z = size * 1.5 * r;
  return { x, z };
}

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function buildIsland({ radius = 3, size = 1, seed = 1 } = {}) {
  const rand = mulberry32(seed);
  const group = new THREE.Group();
  for (let q = -radius; q <= radius; q++) {
    const rMin = Math.max(-radius, -q - radius);
    const rMax = Math.min(radius, -q + radius);
    for (let r = rMin; r <= rMax; r++) {
      const h = 0.2 + rand() * 1.3;
      const geo = new THREE.CylinderGeometry(size * 0.95, size * 0.95, h, 6);
      const mat = new THREE.MeshStandardMaterial({ color: 0x4a8f5c });
      const mesh = new THREE.Mesh(geo, mat);
      const { x, z } = axialToWorld(q, r, size);
      mesh.position.set(x, h / 2, z);
      mesh.userData = { q, r };
      group.add(mesh);
    }
  }
  return group;
}
