import * as THREE from 'three';
import { axialToWorld, hexDistance, buildIsland } from '../src/hexmap.js';

describe('axialToWorld', () => {
  it('places the origin tile at the world origin in xz', () => {
    const { x, z } = axialToWorld(0, 0, 2);
    expect(x).toBeCloseTo(0, 12);
    expect(z).toBeCloseTo(0, 12);
  });
});

describe('buildIsland', () => {
  const radius = 3;
  const size = 1;
  const seed = 42;

  it('contains the centered hexagonal number of tiles for the radius', () => {
    const island = buildIsland({ radius, size, seed });
    // centered hexagonal number: 3r(r-1) + 1 = 37 for r = 3
    expect(island.children.length).toBe(37);

    // sanity: every child is a mesh with axial coords in userData
    for (const mesh of island.children) {
      expect(mesh).toBeInstanceOf(THREE.Mesh);
      expect(Number.isInteger(mesh.userData.q)).toBe(true);
      expect(Number.isInteger(mesh.userData.r)).toBe(true);
    }
  });

  it('uses one CylinderGeometry with 6 radial segments per tile', () => {
    const island = buildIsland({ radius, size, seed });
    for (const mesh of island.children) {
      expect(mesh.geometry).toBeInstanceOf(THREE.CylinderGeometry);
      expect(mesh.geometry.parameters.radialSegments).toBe(6);
    }
  });

  it('positions every adjacent pair exactly size*sqrt(3) apart in xz', () => {
    const island = buildIsland({ radius, size, seed });
    const expected = size * Math.sqrt(3);
    let adjacentPairs = 0;

    for (let i = 0; i < island.children.length; i++) {
      for (let j = i + 1; j < island.children.length; j++) {
        const a = island.children[i];
        const b = island.children[j];
        if (hexDistance(a.userData.q, a.userData.r, b.userData.q, b.userData.r) !== 1) continue;

        adjacentPairs++;
        const dx = a.position.x - b.position.x;
        const dz = a.position.z - b.position.z;
        const dist = Math.hypot(dx, dz);
        expect(Math.abs(dist - expected)).toBeLessThan(1e-9);
      }
    }

    // interior tile has exactly 6 neighbors; total edges in hex grid patch
    expect(adjacentPairs).toBeGreaterThan(0);
  });

  it('keeps all heights within [0.2, 1.5]', () => {
    const island = buildIsland({ radius: 5, size, seed });
    for (const mesh of island.children) {
      expect(mesh.geometry.parameters.height).toBeGreaterThanOrEqual(0.2);
      expect(mesh.geometry.parameters.height).toBeLessThanOrEqual(1.5);
    }
  });

  it('is deterministic per seed', () => {
    const heights = (opts) =>
      buildIsland({ ...opts })
        .children.map((m) => m.geometry.parameters.height)
        .sort((a, b) => a - b);

    expect(heights({ radius, size, seed })).toEqual(
      heights({ radius, size, seed })
    );
    expect(heights({ radius, size, seed })).not.toEqual(
      heights({ radius, size, seed: seed + 1 })
    );
  });
});
