/**
 * Convert axial hex coordinates to world xz coordinates (pointy-top layout).
 * @param {number} q axial column
 * @param {number} r axial row
 * @param {number} size circumradius of a hex tile
 * @returns {{x: number, z: number}}
 */
export function axialToWorld(q, r, size) {
  const x = size * Math.sqrt(3) * (q + r / 2);
  const z = size * 1.5 * r;
  return { x, z };
}

/**
 * Hex distance between two tiles in axial coordinates.
 * @returns {number}
 */
export function hexDistance(q1, r1, q2, r2) {
  const dq = q1 - q2;
  const dr = r1 - r2;
  return (Math.abs(dq) + Math.abs(dr) + Math.abs(dq + dr)) / 2;
}

/** Deterministic PRNG (mulberry32). */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Build an island of hexagonal tile meshes.
 *
 * One CylinderGeometry(…, 6) mesh per hex within hex-distance `radius` of the
 * origin, extruded to a seeded height in [MIN_HEIGHT, MAX_HEIGHT] and
 * positioned via axialToWorld. Each mesh carries userData { q, r }.
 *
 * @param {{radius?: number, size?: number, seed?: number}} options
 * @returns {THREE.Group} group containing one Mesh per tile
 */
export function buildIsland({ radius = 3, size = 1, seed = 1 } = {}) {
  const rand = mulberry32(seed);
  const group = new THREE.Group();
  group.name = 'hex-island';

  for (let q = -radius; q <= radius; q++) {
    const rMin = Math.max(-radius, -q - radius);
    const rMax = Math.min(radius, -q + radius);
    for (let r = rMin; r <= rMax; r++) {
      // Seeded height in [0.2, 1.5]
      const height = MIN_HEIGHT + rand() * (MAX_HEIGHT - MIN_HEIGHT);

      const geometry = new THREE.CylinderGeometry(size, size, height, 6);
      const material = new THREE.MeshStandardMaterial({ color: TILE_COLOR });
      const mesh = new THREE.Mesh(geometry, material);

      const { x, z } = axialToWorld(q, r, size);
      mesh.position.set(x, height / 2, z); // sit on y = 0 plane
      mesh.userData = { q, r };

      group.add(mesh);
    }
  }

  return group;
}

const MIN_HEIGHT = 0.2;
const MAX_HEIGHT = 1.5;
const TILE_COLOR = 0x4a8f5c;
